<?php
// Dynamically reads the default user and DB config generated by Render environment variables
$configFile = '/var/www/FreshRSS/data/config.php';
if (!file_exists($configFile)) {
    exit(0);
}

$config = include($configFile);
$db = $config['db'] ?? [];
$user = $config['default_user'] ?? '';

if (empty($user) || empty($db['host']) || empty($db['base'])) {
    exit(0);
}

$prefix = $db['prefix'] ?? '';
$table = $prefix . $user . '_feed';
$favDir = '/var/www/FreshRSS/data/favicons/';

if (!is_dir($favDir)) {
    mkdir($favDir, 0775, true);
}

try {
    $dbType = $db['type'] ?? 'pgsql';
    $rawHost = $db['host'];
    $host = $rawHost;
    $port = '';

    if (strpos($rawHost, ':') !== false) {
        list($host, $port) = explode(':', $rawHost, 2);
    }

    $dsn = "{$dbType}:host={$host};" . ($port !== '' ? "port={$port};" : "") . "dbname={$db['base']}";
    $pdo = new PDO($dsn, $db['user'], $db['password'], [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
    ]);

    $quote = ($dbType === 'mysql') ? '`' : '"';
    $stmt = $pdo->query("SELECT id, website, url FROM {$quote}{$table}{$quote}");

    $restoredCount = 0;
    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $salt = hash('crc32b', $user . $row['id']);
        $txtFile = $favDir . $salt . '.txt';
        $icoFile = $favDir . $salt . '.ico';

        $website = !empty($row['website']) ? $row['website'] : $row['url'];
        if (!empty($website) && !file_exists($txtFile)) {
            file_put_contents($txtFile, $website);
            @chown($txtFile, 'www-data');
        }

        if (!empty($website) && !file_exists($icoFile)) {
            $feedHost = parse_url($website, PHP_URL_HOST);
            if ($feedHost) {
                $ddgUrl = "https://icons.duckduckgo.com/ip3/{$feedHost}.ico";
                $ctx = stream_context_create([
                    'http' => [
                        'timeout' => 3,
                        'ignore_errors' => false
                    ]
                ]);
                $icoData = @file_get_contents($ddgUrl, false, $ctx);
                if ($icoData !== false && strlen($icoData) > 0) {
                    file_put_contents($icoFile, $icoData);
                    @chown($icoFile, 'www-data');
                    $restoredCount++;
                }
            }
        }
    }
    echo "✅ Favicons restored ({$restoredCount} icons fetched).\n";
} catch (Exception $e) {
    echo "⚠️ Favicon restore skipped: " . $e->getMessage() . "\n";
}
